                    # Translating one to another is not easy, but this should work for simple cases
                    return_schema["pattern"] = re.sub(
                        r"\(\?P<[a-z\d_]+>", "(", s.pattern_str
                    ).replace("/", r"\/")
                else:
                    if flavor != DICT:
                        # If not handled, do not check
                        return return_schema

                    # Schema is a dict

                    required_keys = []
